<script setup lang="ts">
import {commandErrorStatus} from '@/composables/aippt/commandError'

import { cloneJson } from '@/views/aippt/render/clone'

import { ref, watch, onBeforeUnmount } from 'vue'
import { ElMessageBox } from 'element-plus'
import { useAipptEditorStore } from '@/store/modules/aipptEditor'
import {outlineDraftError} from '@/composables/aippt/useOutlineSaveQueue'
import { checkPermi } from '@/utils/permission'
import { api } from '@/api/aippt'
import type { Outline, OutlinePage, Source } from '@/types/aippt'
import { layouts } from '@/views/aippt/render/design'
const props=defineProps<{projectId:string;outline:Outline|null;inputRevision:number;sources:Source[];generating:boolean}>(),emit=defineEmits<{changed:[];task:[id:string]}>();const local=ref<Outline|null>(null),saving=ref(false),error=ref(''),dirty=ref(false),store=useAipptEditorStore();let confirmCommand:{generate:boolean;body:{revision:number;input_revision:number};key:string}|null=null;let timer:ReturnType<typeof setTimeout>|undefined
function queue(){if(!local.value)throw new Error('提纲尚未生成');return store.outlineQueue(props.projectId,local.value,(body,key)=>api.saveOutline(props.projectId,body,key))}
watch(()=>props.outline,v=>{if(!v||v.status==='empty'){if(!dirty.value)local.value=null;return}const q=store.outlineQueue(props.projectId,v,(body,key)=>api.saveOutline(props.projectId,body,key));if(!dirty.value){local.value={...cloneJson(q.state.outline),pages:cloneJson(q.state.draft||q.state.outline.pages)};dirty.value=!!q.state.draft;error.value=q.state.error}},{immediate:true})
function touch(){if(!local.value)return;dirty.value=true;queue().update(local.value.pages);clearTimeout(timer);error.value='';if(!outlineDraftError(local.value.pages))timer=setTimeout(()=>save().catch(()=>{}),800)}
async function save(){clearTimeout(timer);if(!local.value)return;const q=queue(),hadDraft=!!q.state.draft;saving.value=true;try{await q.flush(props.inputRevision);local.value.revision=q.state.outline.revision;dirty.value=!!q.state.draft;error.value='';if(hadDraft)emit('changed')}catch(e:any){error.value=e.message;throw e}finally{saving.value=false}}
async function retry(){if(!local.value)return;const q=queue();if(q.state.conflict){try{await ElMessageBox.confirm('提纲已被其他页面修改。请先核对或复制本地内容，再重新应用到最新版本。','重新应用提纲',{type:'warning'});q.retry(await api.outline(props.projectId));local.value.revision=q.state.outline.revision}catch{return}}else q.retry();await save().catch(()=>{})}
async function confirm(generate:boolean){try{await save();if(!local.value)return;const body={revision:local.value.revision,input_revision:props.inputRevision};if(!confirmCommand||confirmCommand.generate!==generate)confirmCommand={generate,body,key:crypto.randomUUID()};if(generate){const t=await api.confirmAndGenerate(props.projectId,confirmCommand.body,confirmCommand.key);emit('task',t.job_id||t.jobId||t.id||'')}else await api.confirm(props.projectId,confirmCommand.body,confirmCommand.key);confirmCommand=null;emit('changed')}catch(e:any){if(commandErrorStatus(e)===409)confirmCommand=null;error.value=e.message}}
async function unconfirm(){try{if(!local.value)return;await api.unconfirm(props.projectId,{revision:local.value.revision,input_revision:props.inputRevision});emit('changed')}catch(e:any){error.value=e.message}}
function add(){if(!local.value||local.value.pages.length>=20)return;local.value.pages.push({id:crypto.randomUUID(),title:'新增页面',objective:'',key_points:['要点一','要点二'],source_refs:[],layout_id:'bullets',page_role:'content',visual:''});touch()}
function move(i:number,d:number){if(!local.value)return;const p=local.value.pages;const to=i+d;if(to<0||to>=p.length)return;[p[i],p[to]]=[p[to],p[i]];touch()}
const locked=()=>!checkPermi(['aippt:outline:edit'])||props.generating||local.value?.confirmed||local.value?.status==='confirmed'
async function flush(){await save();if(dirty.value)throw new Error('提纲尚未保存')}
defineExpose({flush,isDirty:()=>dirty.value});onBeforeUnmount(()=>clearTimeout(timer))
</script>
<template><section><el-alert v-if="error" type="error" :title="error"><el-button @click="retry">重试保存</el-button></el-alert><template v-if="local"><div class="outline-actions"><span aria-live="polite">{{saving?'正在保存':dirty?'有待保存内容':'已保存'}} · {{local.pages.length}}页</span><el-tag v-if="local.is_stale" type="warning">材料已变化，请重新生成</el-tag><el-button :disabled="locked()||saving||local.pages.length>=20" @click="add">新增提纲页</el-button><el-button :disabled="locked()||saving" @click="save">保存</el-button><el-button v-if="!locked()" v-hasPermi="['aippt:outline:confirm']" :disabled="saving||local.is_stale" @click="confirm(false)">确认提纲</el-button><el-button v-if="!locked()" v-hasPermi="['aippt:outline:confirm','aippt:deck:generate']" type="primary" :disabled="saving||local.is_stale||!checkPermi(['aippt:outline:confirm'])||!checkPermi(['aippt:deck:generate'])" @click="confirm(true)">确认并生成</el-button><el-button v-if="local.confirmed||local.status==='confirmed'" v-hasPermi="['aippt:outline:confirm']" :disabled="generating" @click="unconfirm">取消确认</el-button></div>
<el-card v-for="(page,index) in local.pages" :key="page.id" class="outline-page"><template #header><div class="page-heading"><strong>第{{index+1}}页</strong><el-button :disabled="locked()||index===0" @click="move(index,-1)">上移</el-button><el-button :disabled="locked()||index===local.pages.length-1" @click="move(index,1)">下移</el-button><el-button type="danger" :disabled="locked()||local.pages.length<=5" @click="local.pages.splice(index,1);touch()">删除</el-button></div></template><el-form label-width="85px" :disabled="locked()" @change="touch"><el-form-item label="标题"><el-input v-model="page.title" maxlength="100" @input="touch"/></el-form-item><el-form-item label="目的"><el-input v-model="page.objective" maxlength="300" type="textarea" @input="touch"/></el-form-item><el-form-item label="要点"><div class="full"><div v-for="(_,i) in page.key_points" :key="i" class="point"><el-input v-model="page.key_points[i]" @input="touch"/><el-button :disabled="page.key_points.length<=2" @click="page.key_points.splice(i,1);touch()">删除</el-button></div><el-button :disabled="page.key_points.length>=5" @click="page.key_points.push('');touch()">添加要点（2–5条）</el-button></div></el-form-item><el-form-item label="来源"><el-select v-model="page.source_refs" multiple :multiple-limit="10" @change="touch"><el-option v-for="section in sources.flatMap(s=>s.sections||[])" :key="section.id" :value="section.ref||section.id" :label="section.heading||section.title||section.locator||section.id"/></el-select></el-form-item><el-form-item label="页面角色"><el-select v-model="page.page_role" @change="touch"><el-option v-for="r in ['cover','toc','section','content','summary']" :key="r" :value="r" :label="({cover:'封面',toc:'目录',section:'章节',content:'正文',summary:'总结'} as Record<string,string>)[r]"/></el-select></el-form-item><el-form-item label="固定版式"><el-select v-model="page.layout_id" @change="touch"><el-option v-for="layout in [...layouts.values()]" :key="layout.id" :label="layout.name" :value="layout.id"/></el-select></el-form-item><el-form-item label="配图意图"><el-input v-model="page.visual" maxlength="120" @input="touch"/></el-form-item></el-form></el-card></template><el-empty v-else description="材料就绪后生成提纲"/></section></template>
<style scoped>.outline-actions,.page-heading,.point{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.outline-page{margin-top:16px}.full{width:100%}.point{flex-wrap:nowrap;margin-bottom:8px}.el-select{width:100%}</style>
